import React, { createContext, useContext, useState, useEffect } from 'react';

const PreferencesContext = createContext();

export const usePreferences = () => {
  const context = useContext(PreferencesContext);
  if (!context) {
    throw new Error('usePreferences must be used within a PreferencesProvider');
  }
  return context;
};

export const PreferencesProvider = ({ children }) => {
  const CACHE_KEY = 'userPreferences';
  const CACHE_EXPIRY_KEY = 'userPreferencesExpiry';
  const CACHE_DURATION = 5 * 60 * 1000; // 5 minutes in milliseconds

  // Initialize preferences from cache or defaults
  const [preferences, setPreferences] = useState(() => {
    const cached = getCachedPreferences();
    return cached || {
      emailNotifications: true,
      smsNotifications: false,
      pushNotifications: true,
      theme: 'system',
      language: 'en',
      timezone: 'UTC'
    };
  });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Helper function to get cached preferences
  function getCachedPreferences() {
    try {
      const cached = localStorage.getItem(CACHE_KEY);
      const expiry = localStorage.getItem(CACHE_EXPIRY_KEY);

      if (cached && expiry) {
        const expiryTime = parseInt(expiry, 10);
        if (Date.now() < expiryTime) {
          return JSON.parse(cached);
        } else {
          // Cache expired, remove it
          localStorage.removeItem(CACHE_KEY);
          localStorage.removeItem(CACHE_EXPIRY_KEY);
        }
      }
    } catch (err) {
      console.error('Error reading cached preferences:', err);
    }
    return null;
  }

  // Helper function to cache preferences
  function cachePreferences(prefs) {
    try {
      localStorage.setItem(CACHE_KEY, JSON.stringify(prefs));
      localStorage.setItem(CACHE_EXPIRY_KEY, (Date.now() + CACHE_DURATION).toString());
    } catch (err) {
      console.error('Error caching preferences:', err);
    }
  }

  // Load preferences from API on mount
  useEffect(() => {
    fetchPreferences();
  }, []);

  // Apply theme changes
  useEffect(() => {
    applyTheme(preferences.theme);
  }, [preferences.theme]);

  // Listen for system theme changes when theme is set to 'system'
  useEffect(() => {
    if (preferences.theme !== 'system') return;

    const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');

    const handleSystemThemeChange = (e) => {
      const root = document.documentElement;
      if (e.matches) {
        root.classList.add('dark');
      } else {
        root.classList.remove('dark');
      }
    };

    // Add listener for system theme changes
    mediaQuery.addEventListener('change', handleSystemThemeChange);

    // Cleanup listener on unmount or when theme changes
    return () => {
      mediaQuery.removeEventListener('change', handleSystemThemeChange);
    };
  }, [preferences.theme]);

  const fetchPreferences = async () => {
    try {
      setLoading(true);
      const token = localStorage.getItem('authToken');
      if (!token) {
        setLoading(false);
        return;
      }

      // Check if we have valid cached data
      const cached = getCachedPreferences();
      if (cached) {
        setPreferences(cached);
        setLoading(false);
        // Still fetch in background to update cache
        fetchPreferencesFromAPI();
        return;
      }

      // No cache, fetch from API
      await fetchPreferencesFromAPI();
    } catch (err) {
      console.error('Error fetching preferences:', err);
      setError(err.message);
      setLoading(false);
    }
  };

  const fetchPreferencesFromAPI = async () => {
    try {
      const token = localStorage.getItem('authToken');
      if (!token) return;

      const response = await fetch('http://localhost:8000/api/auth/preferences/', {
        headers: {
          'Authorization': `Token ${token}`,
          'Content-Type': 'application/json'
        }
      });

      if (response.ok) {
        const data = await response.json();
        setPreferences(data);
        cachePreferences(data);
      }
    } catch (err) {
      console.error('Error fetching preferences from API:', err);
    } finally {
      setLoading(false);
    }
  };

  const updatePreferences = async (updates) => {
    try {
      const token = localStorage.getItem('authToken');
      if (!token) {
        throw new Error('No authentication token found');
      }

      const response = await fetch('http://localhost:8000/api/auth/preferences/', {
        method: 'PATCH',
        headers: {
          'Authorization': `Token ${token}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(updates)
      });

      if (response.ok) {
        const data = await response.json();
        setPreferences(data);
        return { success: true, data };
      } else {
        const errorData = await response.json();
        throw new Error(errorData.message || 'Failed to update preferences');
      }
    } catch (err) {
      console.error('Error updating preferences:', err);
      setError(err.message);
      return { success: false, error: err.message };
    }
  };

  const applyTheme = (theme) => {
    const root = document.documentElement;

    if (theme === 'dark') {
      root.classList.add('dark');
    } else if (theme === 'light') {
      root.classList.remove('dark');
    } else if (theme === 'system') {
      // Check system preference
      const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
      if (prefersDark) {
        root.classList.add('dark');
      } else {
        root.classList.remove('dark');
      }
    }
  };

  const value = {
    preferences,
    loading,
    error,
    updatePreferences,
    refreshPreferences: fetchPreferences
  };

  return (
    <PreferencesContext.Provider value={value}>
      {children}
    </PreferencesContext.Provider>
  );
};
